node -e "
import('./src/format.js').then(({ formatBytes }) => {
  const cases = [
    [0, '0 B'],
    [1023, '1023 B'],
    [1024, '1.0 KB'],
    [1536, '1.5 KB'],
    [1076, '1.1 KB'],
    [2048, '2.0 KB'],
    [1280, '1.3 KB'],        // 1.25 -> half-up -> 1.3
    [1792, '1.8 KB'],        // 1.75 -> 1.8
    [1048575, '1023.9 KB'],
    [1048576, '1.0 MB'],
    [1101005, '1.1 MB'],
    [2097152, '2.0 MB'],
    [1310720, '1.3 MB'],     // 1.25 MB -> half-up -> 1.3
    [1073741823, '1024.0 MB'],
  ];
  let bad = 0;
  for (const [input, expected] of cases) {
    const actual = formatBytes(input);
    if (actual !== expected) { bad++; console.log('FAIL', input, '=>', actual, 'expected', expected); }
  }
  console.log(bad === 0 ? 'all ' + cases.length + ' README/boundary checks pass' : bad + ' failures');
})"

